$ErrorActionPreference = 'Stop'
$petDirectory = $PSScriptRoot
$petCompiler = Join-Path $env:WINDIR 'Microsoft.NET\Framework64\v4.0.30319\csc.exe'
if (-not (Test-Path -LiteralPath $petCompiler)) { throw 'Windows .NET Framework 4.8 is required.' }
& $petCompiler /nologo /target:winexe /optimize+ /platform:anycpu /win32manifest:"$petDirectory\src\app.manifest" /win32icon:"$petDirectory\assets\pet.ico" /out:"$petDirectory\XiaoJingDesktopPet.exe" /r:System.dll /r:System.Core.dll /r:System.Drawing.dll /r:System.Windows.Forms.dll /r:System.Management.dll /r:System.Web.Extensions.dll /r:System.Xml.dll "$petDirectory\src\Program.cs" "$petDirectory\src\PetForm.cs" "$petDirectory\src\PetForm.Interactions.cs" "$petDirectory\src\PetForm.LifeVisuals.cs" "$petDirectory\src\PetForm.Recording.cs" "$petDirectory\src\PetServices.cs" "$petDirectory\src\PetServices.Polling.cs" "$petDirectory\src\NvidiaGpuTemperature.cs" "$petDirectory\src\PetForm.Power.cs" "$petDirectory\src\PetForm.Motion.cs" "$petDirectory\src\PetForm.FlightArtwork.cs" "$petDirectory\src\PetForm.Home.cs" "$petDirectory\src\PetForm.WalkArtwork.cs" "$petDirectory\src\WalkingRig.cs" "$petDirectory\src\AnimationSurface.cs" "$petDirectory\src\MappedTransition.cs" "$petDirectory\src\LeisureMotion.cs" "$petDirectory\src\PetForm.LeisureMotion.cs" "$petDirectory\src\PetForm.AirAndTail.cs" "$petDirectory\src\HolidayCalendar.cs" "$petDirectory\src\SolarTermCalendar.cs" "$petDirectory\src\CodexActivityMonitor.cs" "$petDirectory\src\StartupManager.cs" "$petDirectory\src\PetNameDialog.cs" "$petDirectory\src\WeatherLocation.cs" "$petDirectory\src\WeatherLocationDialog.cs"
if ($LASTEXITCODE -ne 0) { throw 'Build failed.' }
Write-Output 'Created XiaoJingDesktopPet.exe.'

